# DK HOA.  Hou - Odder - Aarhus H
#
let ha = path("d3.dk.hoa");

with detail = 4, railway = :first :pax :removed {
    with link = "point.dk.Hou", railway = :station {
        track(ha[:hou - 0.5sw, :hou + 0.5sw]);
        marker(:left :de.bf, ha[:hou] << 0.5mt);
        station(:left:right_align, ha[:hou] << 0.5mt << 1sh + (-1.8dt, 1.8dt),
            span(:bold, "Hou"), "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hou + 0.49sw, :hol - 0.49sw]);
    }

    with link = "point.dk.Holsatia", railway = :station {
        track(ha[:hol - 0.5sw, :hol + 0.5sw]);
        marker(:right :de.hp, ha[:hol] >> 0.5mt);
        station(:right, ha[:hol] >> 0.5mt >> 1sh + (1.5dt, 1dt),
            "Holsatia", "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hol + 0.49sw, :hol + 0.91km]);
        line_label(:right:s, ha[:hol + 0.9km] >> 0.5mt, (0.5dt, 0dt), "HOA");
        track(ha[:hol + 0.89km, :hal - 0.49sw]);
    }

    with link = "point.dk.Halling", railway = :station {
        track(ha[:hal - 0.5sw, :hal + 0.5sw]);
        marker(:left :de.hp, ha[:hal] << 0.5mt);
        marker(:left :de.exbf, ha[:hal] << 0.5mt);
        station(:left, ha[:hal] << 0.5mt << 1.4sh + (-1.8dt, 1.7dt),
            "Halling", "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:hal + 0.49sw, :bov - 0.49sw]);
    }

    with link = "point.dk.Bovlstrup", railway = :station {
        track(ha[:bov - 0.5sw, :bov + 0.5sw]);
        marker(:right :de.bf, ha[:bov] >> 0.5mt);
        station(:right, ha[:bov] >> 0.5mt >> 1sh + (2.0dt, 0.5dt),
            "Bovlstrup", "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:bov + 0.49sw, :eri - 0.49sw]);
    }

    with link = "point.dk.Eriksminde", railway = :station {
        track(ha[:eri - 0.5sw, :eri + 0.5sw]);
        marker(:right :de.hp, ha[:eri] >> 0.5mt);
        station(:right, ha[:eri] >> 0.5mt >> 1sh + (1.9dt, 0.6dt),
            "Eriksminde", "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:eri + 0.49sw, :nra - 0.49sw]);
    }

    with link = "point.dk.Neder-Randlev", railway = :station {
        track(ha[:nra - 0.5sw, :nra + 0.5sw]);
        marker(:right :de.hp, ha[:nra] >> 0.5mt);
        marker(:right :de.exbf, ha[:nra] >> 0.5mt);
        station(:top, ha[:nra] >> 0.5mt >> 1.4sh + (1.8dt, -1dt),
            "Neder Randlev", "HOA: ??"
        );
    }

    with link = "line.dk.HOA" {
        track(ha[:nra + 0.49sw, :nra + 1.41km]);
        line_label(:right:s, ha[:nra + 1.4km] >> 0.5mt, (0.3dt, 0dt), "HOA");
        track(ha[:nra + 1.39km, :odd.xh]);
        track(:lor, ha[:odd.xh - 0.1dl, :odd.yh + 0.1dl]);
    }
}

