            span(:bold, "Odder"),
            hbox(:center:top,
                vbox(:right:top,
                    span(:removed, "HSO: "),
                    "HOA: "
                ),
                vbox(:sep:top,
                    hbox(:sep:base :removed, "34,", anchor(), "0"),
